import * as T from './vendor/three.module.js';
const ballGeo=new T.IcosahedronGeometry(1,3),shardGeo=new T.BoxGeometry(1,.12,1),emberGeo=new T.IcosahedronGeometry(.1,0);
const emberMat=new T.MeshBasicMaterial({color:0xffb44f,toneMapped:false});
const charMat=new T.MeshStandardMaterial({color:0x201c19,roughness:1,metalness:.2});
function smokeTexture(){let c=document.createElement('canvas');c.width=c.height=128;let x=c.getContext('2d'),g=x.createRadialGradient(64,64,0,64,64,62);g.addColorStop(0,'rgba(255,255,255,.72)');g.addColorStop(.35,'rgba(255,255,255,.46)');g.addColorStop(1,'rgba(255,255,255,0)');x.fillStyle=g;x.fillRect(0,0,128,128);return new T.CanvasTexture(c)}
const blastVertex=`varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`;
const blastFragment=`varying vec2 vUv;uniform sampler2D atlas;uniform float frame;uniform float opacity;
vec4 cell(float n){float col=mod(n,4.);float row=3.-floor(n/4.);vec2 uv=(vec2(col,row)+.004+vUv*.992)/4.;return texture2D(atlas,uv);}
void main(){float first=floor(frame);vec4 a=cell(first),b=cell(min(15.,first+1.));a.rgb*=a.a;b.rgb*=b.a;vec4 c=mix(a,b,fract(frame));c.rgb/=max(.001,c.a);float edge=smoothstep(0.,.15,min(min(vUv.x,1.-vUv.x),min(vUv.y,1.-vUv.y)));c.a*=opacity*edge;if(c.a<.015)discard;c.rgb*=1.+max(0.,1.-frame/7.)*.6;gl_FragColor=c;
#include <tonemapping_fragment>
#include <colorspace_fragment>
}`;
const billboardGeo=new T.PlaneGeometry(1,1);

export class Effects{
 constructor(scene,sound,camera=null){this.scene=scene;this.sound=sound;this.camera=camera;this.atlas=null;if(typeof document!=='undefined'&&document.createElementNS){this.atlas=new T.TextureLoader().load(new URL('assets/vfx/explosion-atlas-v1.png',import.meta.url).href);this.atlas.colorSpace=T.SRGBColorSpace;this.atlas.minFilter=T.LinearFilter;this.atlas.generateMipmaps=false;}this.items=[];this.emitters=[];this.smokeMap=smokeTexture();this.shake=0;this.flashLights=Array.from({length:2},()=>{const light=new T.PointLight(0xff9d35,0,120,1);scene.add(light);return light});}
 add(mesh,data){this.scene.add(mesh);this.items.push({mesh,...data});return mesh}
 explosion(pos,size=1,big=false){const count=big?6:1;
  for(let i=0;i<count;i++){let material=new T.ShaderMaterial({uniforms:{atlas:{value:this.atlas},frame:{value:0},opacity:{value:1}},vertexShader:blastVertex,fragmentShader:blastFragment,transparent:true,depthWrite:false,side:T.DoubleSide});let m=new T.Mesh(billboardGeo,material);m.position.copy(pos);if(i)m.position.add(new T.Vector3((Math.random()-.5)*size*1.5,Math.random()*size*.8,(Math.random()-.5)*size*1.8));if(this.camera)m.quaternion.copy(this.camera.quaternion);this.add(m,{kind:'atlas',age:-i*.08,life:big?3.1:2.0,scale:size*(i===0?3.8:1.4+Math.random()),ownsMaterial:true})}
  for(let i=0;i<(big?85:24);i++){let mesh=new T.Mesh(emberGeo,emberMat);mesh.position.copy(pos);this.add(mesh,{kind:'ember',age:0,life:.7+Math.random()*2,v:new T.Vector3((Math.random()-.5)*size*9,(Math.random()-.2)*size*7,(Math.random()-.5)*size*9)})}
  const light=this.flashLights.reduce((a,b)=>a.intensity<b.intensity?a:b);light.intensity=big?650:100;light.distance=size*9;light.position.copy(pos);this.shake=Math.max(this.shake,big?1:.16);this.sound?.effect(big?'bomb':'explosion');if(big)this.shockwave(pos,size);
 }
 aircraft(model,type='fighter'){model.updateWorldMatrix(true,true);const pos=model.getWorldPosition(new T.Vector3()),parts=[];model.traverse(m=>{if(m.isMesh&&m.visible){m.geometry.computeBoundingBox();let size=m.geometry.boundingBox.getSize(new T.Vector3());if(Math.max(size.x,size.y,size.z)>.85)parts.push(m)}});
  for(const m of parts.slice(0,type==='bomber'?16:11)){let p=m.getWorldPosition(new T.Vector3()),v=p.sub(pos).multiplyScalar(9);v.y+=3+Math.random()*6;v.z+=14;const debris=this.eject(m,v);this.trail(debris,.8,.22)}
  const first=this.items.length;this.explosion(pos,type==='bomber'?3.8:2.6,type==='bomber');for(const item of this.items.slice(first))if(item.kind==='atlas')item.v=new T.Vector3(0,1,12);if(type!=='bomber')this.smoke(pos,1.4,new T.Vector3(0,2,12),3.5);
 }

 smoke(pos,size=1,v=new T.Vector3(0,1,0),life=3){const mat=new T.SpriteMaterial({map:this.smokeMap,color:0x312a26,transparent:true,opacity:.7,depthWrite:false,rotation:Math.random()*6.28});let m=new T.Sprite(mat);m.position.copy(pos);this.add(m,{kind:'smoke',age:0,life,scale:size,v,ownsMaterial:true})}
 trail(anchor,duration=4,size=.5){this.emitters.push({anchor,remaining:duration,clock:0,size})}
 shockwave(pos,size){let geo=new T.RingGeometry(.93,1,96),mat=new T.MeshBasicMaterial({color:0xc6a57a,transparent:true,opacity:.22,side:T.DoubleSide,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false});let ring=new T.Mesh(geo,mat);ring.rotation.x=-Math.PI/2;ring.position.copy(pos);ring.position.y=-3.2;this.add(ring,{kind:'ring',age:0,life:2.4,scale:size*8,ownsGeometry:true,ownsMaterial:true})}
 eject(mesh,velocity){mesh.updateWorldMatrix(true,false);const clone=mesh.isMesh?new T.Mesh(mesh.geometry,mesh.material):mesh.clone(true);mesh.getWorldPosition(clone.position);mesh.getWorldQuaternion(clone.quaternion);mesh.getWorldScale(clone.scale);mesh.visible=false;clone.castShadow=true;this.add(clone,{kind:'debris',age:0,life:4.5,v:velocity,spin:new T.Vector3(Math.random()*4,Math.random()*5,Math.random()*4)});return clone}
 turret(t){if(t.destroyed)return false;t.destroyed=true;const pivot=t.root?t.root.userData.head:t.mesh;pivot.updateWorldMatrix(true,true);const pos=pivot.getWorldPosition(new T.Vector3());const barrels=t.root?t.root.userData.barrels:pivot.children.filter(m=>m.isMesh&&m.geometry.type==='CylinderGeometry');for(let b of barrels)this.eject(b,new T.Vector3((Math.random()-.5)*10,8+Math.random()*6,(Math.random()-.5)*12));pivot.traverse(m=>{if(m.isMesh&&m.visible)m.material=charMat});pivot.rotation.z+=.28;pivot.rotation.x+=.2;if(t.lamp)t.lamp.visible=false;if(t.root)t.root.userData.lamp.visible=false;this.explosion(pos,2.2);this.trail(pivot,6,.65);return true}
 fragments(source,pieces=16){const geometry=source.geometry,index=geometry.index,positions=geometry.attributes.position,normals=geometry.attributes.normal,total=index?index.count:positions.count,per=Math.max(3,Math.ceil(total/pieces/3)*3);source.updateWorldMatrix(true,false);
  for(let offset=0;offset<total;offset+=per){let data=[],normal=[],center=new T.Vector3(),count=Math.min(per,total-offset);for(let i=0;i<count;i++){let j=index?index.getX(offset+i):offset+i;let p=new T.Vector3().fromBufferAttribute(positions,j);data.push(p.x,p.y,p.z);center.add(p);if(normals)normal.push(normals.getX(j),normals.getY(j),normals.getZ(j))}center.multiplyScalar(1/count);for(let i=0;i<data.length;i+=3){data[i]-=center.x;data[i+1]-=center.y;data[i+2]-=center.z}let g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(data,3));if(normal.length)g.setAttribute('normal',new T.Float32BufferAttribute(normal,3));else g.computeVertexNormals();let m=new T.Mesh(g,source.material);source.getWorldQuaternion(m.quaternion);source.getWorldScale(m.scale);m.position.copy(source.localToWorld(center.clone()));let v=center.clone().applyQuaternion(source.quaternion).multiplyScalar(.85);v.y+=5+Math.random()*8;this.add(m,{kind:'debris',age:0,life:6,v,spin:new T.Vector3((Math.random()-.5)*4,(Math.random()-.5)*4,(Math.random()-.5)*4),ownsGeometry:true})}
 }
 breakup(model){model.updateWorldMatrix(true,true);const bounds=new T.Box3().setFromObject(model),center=bounds.getCenter(new T.Vector3()),size=bounds.getSize(new T.Vector3());const hull=model.children.find(m=>m.isMesh&&m.geometry.type==='BufferGeometry');if(hull)this.fragments(hull,20);model.traverse(m=>{if(m.isMesh&&m.userData.sail)this.fragments(m,8)});let small=[];model.traverse(m=>{if(m.isMesh&&m.visible&&!m.userData.sail){m.geometry.computeBoundingBox();const s=m.geometry.boundingBox.getSize(new T.Vector3());if(Math.max(s.x,s.y,s.z)<4&&Math.random()<.12)small.push(m)}});for(const m of small.slice(0,20)){let p=m.getWorldPosition(new T.Vector3()),v=p.sub(center).multiplyScalar(1.15);v.y+=7;this.eject(m,v)}const metal=hull?.material||charMat;
  for(let i=0;i<20;i++){const mesh=new T.Mesh(shardGeo,i%4===0?charMat:metal);mesh.position.copy(center).add(new T.Vector3((Math.random()-.5)*size.x*.8,(Math.random()-.5)*size.y*.5,(Math.random()-.5)*size.z*.7));mesh.scale.set(.4+Math.random()*1.2,.5+Math.random(),.5+Math.random()*1.8);let v=mesh.position.clone().sub(center).multiplyScalar(1.2);v.y+=4+Math.random()*9;this.add(mesh,{kind:'debris',age:0,life:5,v,spin:new T.Vector3(Math.random()*3,Math.random()*3,Math.random()*4)})}model.visible=false;
 }

 update(dt){for(const light of this.flashLights)light.intensity*=Math.exp(-dt*6);this.shake=Math.max(0,this.shake-dt*.75);for(let emitter of [...this.emitters]){emitter.remaining-=dt;emitter.clock-=dt;if(emitter.clock<=0&&emitter.anchor.parent){let pos=emitter.anchor.getWorldPosition(new T.Vector3());this.smoke(pos,emitter.size,new T.Vector3((Math.random()-.5)*.6,1.4,0),2.4);emitter.clock=.22}if(emitter.remaining<=0)this.emitters.splice(this.emitters.indexOf(emitter),1)}for(let item of [...this.items]){item.age+=dt;const t=Math.max(0,item.age/item.life),m=item.mesh;if(item.kind==='atlas'){m.visible=item.age>=0;if(this.camera)m.quaternion.copy(this.camera.quaternion);m.material.uniforms.frame.value=Math.min(15,Math.max(0,t)*15);m.material.uniforms.opacity.value=1-Math.max(0,(t-.8)/.2);m.scale.setScalar(item.scale*(1+t*.12));if(item.v)m.position.addScaledVector(item.v,dt)}else if(item.kind==='smoke'){m.position.addScaledVector(item.v,dt);m.scale.setScalar(item.scale*(1+t*3.3));m.material.opacity=Math.sin(Math.min(1,t)*Math.PI)*.56;m.material.rotation+=dt*.13}else if(item.kind==='light')m.intensity*=Math.exp(-dt*6);else if(item.kind==='ring'){m.scale.setScalar(1+item.scale*t);m.material.opacity=(1-t)*.22}else if(item.kind==='debris'||item.kind==='ember'){item.v.y-=dt*(item.kind==='debris'?7:3);m.position.addScaledVector(item.v,dt);if(item.spin){m.rotation.x+=item.spin.x*dt;m.rotation.y+=item.spin.y*dt;m.rotation.z+=item.spin.z*dt}if(item.kind==='ember')m.scale.setScalar(Math.max(.01,1-t))}if(t>=1){this.scene.remove(m);if(item.ownsMaterial)m.material.dispose();if(item.ownsGeometry)m.geometry.dispose();this.items.splice(this.items.indexOf(item),1)}}}
 clear(){for(const light of this.flashLights)light.intensity=0;for(let item of this.items){this.scene.remove(item.mesh);if(item.ownsMaterial)item.mesh.material.dispose();if(item.ownsGeometry)item.mesh.geometry.dispose()}this.items.length=0;this.emitters.length=0;this.shake=0;}
}
